            "CREATE TABLE projection_outbox_events (\n\tprojection_event_id CHAR(32) NOT NULL, \n\tgeneration_id CHAR(32) NOT NULL, \n\tprojection_epoch_id CHAR(32) NOT NULL, \n\tsource_route VARCHAR(16) NOT NULL, \n\tcommand_execution_id CHAR(32), \n\ttask_id CHAR(32) NOT NULL, \n\tevent_type VARCHAR(32) NOT NULL, \n\taggregate_sequence BIGINT NOT NULL, \n\tidempotency_key VARCHAR(64) NOT NULL, \n\tintent_payload JSON NOT NULL, \n\tintent_sha256 VARCHAR(64) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tclaim_owner VARCHAR(256), \n\tclaim_token CHAR(32), \n\tclaim_expires_at DATETIME, \n\toutbox_revision BIGINT NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tterminal_at DATETIME, \n\tCONSTRAINT pk_projection_outbox_events PRIMARY KEY (projection_event_id), \n\tCONSTRAINT ck_projection_outbox_events_event_type_allowed CHECK (event_type IN ('create_task','update_task_document','move_task','set_completion','reproject')), \n\tCONSTRAINT ck_projection_outbox_events_source_route_allowed CHECK (source_route IN ('command','service')), \n\tCONSTRAINT ck_projection_outbox_events_exact_source_route CHECK ((source_route = 'command' AND command_execution_id IS NOT NULL) OR (source_route = 'service' AND command_execution_id IS NULL)), \n\tCONSTRAINT ck_projection_outbox_events_positive_revisions CHECK (aggregate_sequence > 0 AND outbox_revision > 0), \n\tCONSTRAINT ck_projection_outbox_events_hash_lengths CHECK (length(idempotency_key) = 64 AND length(intent_sha256) = 64), \n\tCONSTRAINT ck_projection_outbox_events_state_allowed CHECK (state IN ('pending','claimed','applied','uncertain','blocked','superseded')), \n\tCONSTRAINT ck_projection_outbox_events_claim_state_consistent CHECK ((state = 'claimed' AND claim_owner IS NOT NULL AND claim_token IS NOT NULL AND claim_expires_at IS NOT NULL AND terminal_at IS NULL) OR (state = 'pending' AND claim_owner IS NULL AND claim_token IS NULL AND claim_expires_at IS NULL AND terminal_at IS NULL) OR (state IN ('applied','uncertain','blocked','superseded') AND claim_owner IS NULL AND claim_token IS NULL AND claim_expires_at IS NULL AND terminal_at IS NOT NULL)), \n\tCONSTRAINT uq_projection_task_sequence UNIQUE (generation_id, task_id, aggregate_sequence), \n\tCONSTRAINT fk_projection_outbox_events_generation_id_authority_generations FOREIGN KEY(generation_id) REFERENCES authority_generations (generation_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_outbox_events_projection_epoch_id_projection_epochs FOREIGN KEY(projection_epoch_id) REFERENCES projection_epochs (projection_epoch_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_outbox_events_command_execution_id_command_executions FOREIGN KEY(command_execution_id) REFERENCES command_executions (execution_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_outbox_events_task_id_dish_tasks FOREIGN KEY(task_id) REFERENCES dish_tasks (task_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_projection_outbox_events_idempotency_key UNIQUE (idempotency_key)\n)",
            "CREATE TABLE projection_attempts (\n\tattempt_id CHAR(32) NOT NULL, \n\tprojection_event_id CHAR(32) NOT NULL, \n\tattempt_number INTEGER NOT NULL, \n\tworker_id VARCHAR(256) NOT NULL, \n\trequest_identity VARCHAR(256) NOT NULL, \n\tintended_external_id VARCHAR(256), \n\trequest_payload JSON NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tstarted_at DATETIME NOT NULL, \n\tterminal_at DATETIME, \n\tCONSTRAINT pk_projection_attempts PRIMARY KEY (attempt_id), \n\tCONSTRAINT ck_projection_attempts_positive_attempt CHECK (attempt_number > 0), \n\tCONSTRAINT ck_projection_attempts_request_hash_length CHECK (length(request_sha256) = 64), \n\tCONSTRAINT ck_projection_attempts_state_allowed CHECK (state IN ('dispatched','confirmed','not_applied','uncertain','blocked')), \n\tCONSTRAINT ck_projection_attempts_terminal_time_consistent CHECK ((state = 'dispatched' AND terminal_at IS NULL) OR (state <> 'dispatched' AND terminal_at IS NOT NULL)), \n\tCONSTRAINT uq_projection_attempt_number UNIQUE (projection_event_id, attempt_number), \n\tCONSTRAINT fk_projection_attempts_projection_event_id_projection_outbox_events FOREIGN KEY(projection_event_id) REFERENCES projection_outbox_events (projection_event_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_projection_attempts_request_identity UNIQUE (request_identity)\n)",
            "CREATE TABLE projection_observations (\n\tobservation_id CHAR(32) NOT NULL, \n\tattempt_id CHAR(32) NOT NULL, \n\tobservation_sequence INTEGER NOT NULL, \n\tobservation_kind VARCHAR(24) NOT NULL, \n\tobserved_applied BOOLEAN, \n\tobserved_identity VARCHAR(256), \n\treread_complete BOOLEAN NOT NULL, \n\tevidence JSON NOT NULL, \n\tevidence_sha256 VARCHAR(64) NOT NULL, \n\tobserved_at DATETIME NOT NULL, \n\tCONSTRAINT pk_projection_observations PRIMARY KEY (observation_id), \n\tCONSTRAINT ck_projection_observations_positive_observation_sequence CHECK (observation_sequence > 0), \n\tCONSTRAINT ck_projection_observations_kind_allowed CHECK (observation_kind IN ('preflight','reread','marker_search','drift_scan')), \n\tCONSTRAINT ck_projection_observations_evidence_hash_length CHECK (length(evidence_sha256) = 64), \n\tCONSTRAINT uq_attempt_observation_sequence UNIQUE (attempt_id, observation_sequence), \n\tCONSTRAINT fk_projection_observations_attempt_id_projection_attempts FOREIGN KEY(attempt_id) REFERENCES projection_attempts (attempt_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE projection_adjudications (\n\tadjudication_id CHAR(32) NOT NULL, \n\tattempt_id CHAR(32) NOT NULL, \n\tobservation_id CHAR(32) NOT NULL, \n\tadjudication_sequence INTEGER NOT NULL, \n\toutcome VARCHAR(16) NOT NULL, \n\tdecided_by VARCHAR(24) NOT NULL, \n\tdecision_reason TEXT NOT NULL, \n\tdecided_at DATETIME NOT NULL, \n\tCONSTRAINT pk_projection_adjudications PRIMARY KEY (adjudication_id), \n\tCONSTRAINT ck_projection_adjudications_positive_adjudication_sequence CHECK (adjudication_sequence > 0), \n\tCONSTRAINT ck_projection_adjudications_outcome_allowed CHECK (outcome IN ('confirmed','not_applied','uncertain','blocked')), \n\tCONSTRAINT ck_projection_adjudications_decider_allowed CHECK (decided_by IN ('automatic','marco')), \n\tCONSTRAINT uq_attempt_adjudication_sequence UNIQUE (attempt_id, adjudication_sequence), \n\tCONSTRAINT fk_projection_adjudications_attempt_id_projection_attempts FOREIGN KEY(attempt_id) REFERENCES projection_attempts (attempt_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_projection_adjudications_observation_id UNIQUE (observation_id), \n\tCONSTRAINT fk_projection_adjudications_observation_id_projection_observations FOREIGN KEY(observation_id) REFERENCES projection_observations (observation_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE projection_create_correlations (\n\tcorrelation_id CHAR(32) NOT NULL, \n\tprojection_event_id CHAR(32) NOT NULL, \n\tmarker VARCHAR(256) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tmatched_external_id VARCHAR(256), \n\tmatch_count INTEGER, \n\tmapping_id CHAR(32), \n\tcorrelation_revision BIGINT NOT NULL, \n\tlast_evidence JSON NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tCONSTRAINT pk_projection_create_correlations PRIMARY KEY (correlation_id), \n\tCONSTRAINT ck_projection_create_correlations_state_allowed CHECK (state IN ('pending','bound','ambiguous','not_found')), \n\tCONSTRAINT ck_projection_create_correlations_positive_revision CHECK (correlation_revision > 0), \n\tCONSTRAINT ck_projection_create_correlations_state_payload_consistent CHECK ((state = 'pending' AND matched_external_id IS NULL AND mapping_id IS NULL) OR (state = 'bound' AND matched_external_id IS NOT NULL AND match_count = 1 AND mapping_id IS NOT NULL) OR (state = 'ambiguous' AND match_count > 1 AND mapping_id IS NULL) OR (state = 'not_found' AND match_count = 0 AND mapping_id IS NULL)), \n\tCONSTRAINT uq_projection_create_correlations_projection_event_id UNIQUE (projection_event_id), \n\tCONSTRAINT fk_projection_create_correlations_projection_event_id_projection_outbox_events FOREIGN KEY(projection_event_id) REFERENCES projection_outbox_events (projection_event_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_projection_create_correlations_marker UNIQUE (marker)\n)",
            "CREATE TABLE projection_drift_events (\n\tdrift_event_id CHAR(32) NOT NULL, \n\tgeneration_id CHAR(32) NOT NULL, \n\ttask_id CHAR(32) NOT NULL, \n\ttask_mapping_id CHAR(32) NOT NULL, \n\tdrift_kind VARCHAR(32) NOT NULL, \n\texternal_snapshot_sha256 VARCHAR(64) NOT NULL, \n\tauthoritative_snapshot_sha256 VARCHAR(64) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\treproject_event_id CHAR(32), \n\tdrift_revision BIGINT NOT NULL, \n\tevidence JSON NOT NULL, \n\tdetected_at DATETIME NOT NULL, \n\tresolved_at DATETIME, \n\tCONSTRAINT pk_projection_drift_events PRIMARY KEY (drift_event_id), \n\tCONSTRAINT ck_projection_drift_events_kind_allowed CHECK (drift_kind IN ('document','placement','completion','unknown_task')), \n\tCONSTRAINT ck_projection_drift_events_state_allowed CHECK (state IN ('open','reprojected','isolated')), \n\tCONSTRAINT ck_projection_drift_events_positive_revision CHECK (drift_revision > 0), \n\tCONSTRAINT ck_projection_drift_events_hash_lengths CHECK (length(external_snapshot_sha256) = 64 AND length(authoritative_snapshot_sha256) = 64), \n\tCONSTRAINT ck_projection_drift_events_resolution_consistent CHECK ((state = 'open' AND reproject_event_id IS NULL AND resolved_at IS NULL) OR (state = 'reprojected' AND reproject_event_id IS NOT NULL AND resolved_at IS NOT NULL) OR (state = 'isolated' AND resolved_at IS NOT NULL)), \n\tCONSTRAINT fk_projection_drift_events_generation_id_authority_generations FOREIGN KEY(generation_id) REFERENCES authority_generations (generation_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_drift_events_task_id_dish_tasks FOREIGN KEY(task_id) REFERENCES dish_tasks (task_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_drift_events_task_mapping_id_task_projection_mappings FOREIGN KEY(task_mapping_id) REFERENCES task_projection_mappings (mapping_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_drift_events_reproject_event_id_projection_outbox_events FOREIGN KEY(reproject_event_id) REFERENCES projection_outbox_events (projection_event_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE projection_reconciliation_runs (\n\treconciliation_run_id CHAR(32) NOT NULL, \n\tgeneration_id CHAR(32) NOT NULL, \n\tprojection_epoch_id CHAR(32) NOT NULL, \n\tcorpus_identity VARCHAR(256) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\texpected_items BIGINT NOT NULL, \n\tprocessed_items BIGINT NOT NULL, \n\tstarted_at DATETIME NOT NULL, \n\tcompleted_at DATETIME, \n\tCONSTRAINT pk_projection_reconciliation_runs PRIMARY KEY (reconciliation_run_id), \n\tCONSTRAINT ck_projection_reconciliation_runs_status_allowed CHECK (status IN ('running','complete','blocked')), \n\tCONSTRAINT ck_projection_reconciliation_runs_nonnegative_counts CHECK (expected_items >= 0 AND processed_items >= 0), \n\tCONSTRAINT ck_projection_reconciliation_runs_count_not_over_expected CHECK (processed_items <= expected_items), \n\tCONSTRAINT ck_projection_reconciliation_runs_terminal_time_consistent CHECK ((status = 'running' AND completed_at IS NULL) OR (status IN ('complete','blocked') AND completed_at IS NOT NULL)), \n\tCONSTRAINT uq_reconciliation_corpus UNIQUE (generation_id, projection_epoch_id, corpus_identity), \n\tCONSTRAINT fk_projection_reconciliation_runs_generation_id_authority_generations FOREIGN KEY(generation_id) REFERENCES authority_generations (generation_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_projection_reconciliation_runs_projection_epoch_id_projection_epochs FOREIGN KEY(projection_epoch_id) REFERENCES projection_epochs (projection_epoch_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE projection_reconciliation_items (\n\treconciliation_item_id CHAR(32) NOT NULL, \n\treconciliation_run_id CHAR(32) NOT NULL, \n\titem_identity VARCHAR(256) NOT NULL, \n\tentity_kind VARCHAR(32) NOT NULL, \n\tmapping_id CHAR(32), \n\toutcome VARCHAR(24) NOT NULL, \n\tevidence JSON NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tCONSTRAINT pk_projection_reconciliation_items PRIMARY KEY (reconciliation_item_id), \n\tCONSTRAINT ck_projection_reconciliation_items_entity_kind_allowed CHECK (entity_kind IN ('project','section','task')), \n\tCONSTRAINT ck_projection_reconciliation_items_outcome_allowed CHECK (outcome IN ('matched','reprojected','unknown_external','blocked')), \n\tCONSTRAINT uq_reconciliation_item_identity UNIQUE (reconciliation_run_id, item_identity), \n\tCONSTRAINT fk_projection_reconciliation_items_reconciliation_run_id_projection_reconciliation_runs FOREIGN KEY(reconciliation_run_id) REFERENCES projection_reconciliation_runs (reconciliation_run_id) ON DELETE RESTRICT\n)",
